// visca catalogo con sesion iniciada
import React from 'react';
import { Link } from 'react-router-dom';
//estilos
import "../../components/cliente.css";
//imagenes

// header y footer
import Header from '../../components/Header_c.jsx'; 
import Footer from '../../components/Footer.jsx';

const Catalogo_c = () => {
    return (
    <>
    <Header />

    <main>
        <section className="contenido-inicio">
            <h1>Catálogo de productos</h1>  
            <p>Explora nuestros productos tejidos a mano, hechos con amor y dedicación</p>

            <div className="contenedor-productos">

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>1 Virgencitas de crochet de 20 CM</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>2 Ramo de tulipanes tejidos</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>3 Cubrelecho español</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>4 Amigurumi Stitch</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>5 Amigurumi perrito</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>6 Accesorios para maleta</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>7 Llavero tejido hollow knight</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>8 Sábanas para cama doble</p>
                </div>
                {/*Cierre del link*/}

            </div>
        </section>
    </main>

    <Footer />
    </>
    );
    };

    export default Catalogo_c;
